INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('sunscreen', 5, '10/10', 'Ich durfte das Sonnenschutzfluid schon vorab testen und bin wirklich sehr zufrieden. Ich trage es täglich über meinem Serum und meine Haut fühlt sich den ganzen Tag leicht und gepflegt an. Andere Sonnencremes sind mir oft zu speckig und führen zu Unreinheiten. Das habe ich hier überhaupt nicht. Für mich eine klare 10/10!', 'Laura', 'kathrin.fesenmeyer@t-online.de', 'approved', '2026-03-31 11:54:15', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('sunscreen', 5, 'Super angenehm, toll!', 'Vielen Dank, dass ich die Sonnencreme testen durfte. Ich finde sie wirklich toll. Ich habe eher trockene Haut und komme trotzdem sehr gut mit der leichten Textur zurecht. Sie fühlt sich angenehm pflegend an und hinterlässt ein schönes, natürliches Finish. Für mich ist sie inzwischen ein fester Bestandteil meiner täglichen Routine geworden und gibt mir im Alltag ein sehr gutes Gefühl.', 'Birgit', 'kathrin@herbsom.de', 'approved', '2026-03-31 12:01:29', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('sunscreen', 5, 'Endlich eine Sonnencreme die nicht fettet', 'Mit den meisten Sonnecremes glänze ich und bin weiß. Ich habe den Sonnenschutz in den letzten Wochen getestet und die Textur ist super leicht. Auch perfekt unter Make-up. Und was ich auch ziemlich cool finde, dass ein Blaulichtfilter drin ist, ich arbeite viel am PC und sich dort gegen Blaulicht zu schützen ist toll. Habe ich bisher auch noch bei keiner anderen Sonnencreme gesehen. Bin rundum zufrieden.', 'Estelle', 'alica.klemm@gmail.com', 'approved', '2026-03-31 12:07:03', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('sunscreen', 5, 'Gute Bewertung', 'Mega, auch beim Sport richtig angenehm. Kein Kleben, kein Schwitzen und kein komischer Geruch.', 'Simon', 'kathrin@herbsom.de', 'approved', '2026-03-31 15:31:54', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('sunscreen', 5, 'Gute Bewertung', 'Nutze Herbsom schon länger und die Sonnencreme jetzt seit ein paar Tagen täglich morgens.
Passt für mich richtig gut in die Routine, morgens schnell und unkompliziert, abends Wohlfühlmoment. Fühlt sich einfach gut an 😊', 'Marina', 'kathrin@herbsom.de', 'approved', '2026-04-07 09:26:55', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('sunscreen', 5, 'Mein einziges Hautpflegeprodukt', 'Ich bin 30 geworden und da denkt man als Mann auch auf einmal an die Hautpflege. Ich wollte eine Creme mit Sonnenschutz, die ich morgens auftrage und fertig. Bin mit dieser hier sehr zufrieden, erfüllt genau ihren Zweck. Man sieht nicht eingecremt aus und es läuft mir auch nicht in die Augen wenn ich Sport mache. Scheint so als würde ich erstmal bei der hier bleiben.', 'Christian', 'zveroslav@web.de', 'approved', '2026-04-07 13:43:32', 0, 0);
