INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Finde ich sehr gut!', 'Die Creme finde ich sehr angenehm, auch das "Anmischen" gelingt, ohne zu kleckern, was ich anfänglichst befürchtet hatte.
Das Produkt, sowie die Verpackung machen einen sehr hochwertigen Eindruck.
Ob und wie die Creme "wirkt", kann allerdings erst der Langzeittest zeigen, so erst einmal fühlt sie sich richtig toll auf der Haut an, spannen oder brennen tut sie nach dem Auftragen auch nicht, was bei mir nicht selbstverständlich ist!!!', 'Angela S.', 'angela.schlueschen@web.de', 'approved', '2026-04-23 11:12:01', 0, 0);